import ast
def validate_node(node):
    if isinstance(node, (ast.Constant, ast.Name)):
        return True
    elif isinstance(node, ast.Compare):
        return validate_node(node.left) and all(validate_node(c) for c in node.comparators)
    elif isinstance(node, ast.BoolOp):
        return all(validate_node(v) for v in node.values)
    elif isinstance(node, ast.UnaryOp):
        return isinstance(node.op, ast.Not) and validate_node(node.operand)
    elif isinstance(node, (ast.And, ast.Or, ast.Not, ast.Eq, ast.NotEq, ast.Lt, ast.LtE, ast.Gt, ast.GtE)):
        return True
    return False

